pub const SCHEMA_BLOB_MAGIC: [u8; 8] = *b"OPBLOB01";
pub const SCHEMA_BLOB_VERSION: u32 = 1;

const SCHEMA_BLOB_HEADER_SIZE: usize = SCHEMA_BLOB_MAGIC.len() + 4 + 8;

