}

impl RegistryInner {
    fn new() -> (
        Self,
        broadcast::Sender<crate::proto::registry::RegistryEvent>,
    ) {
        let (tx, _) = broadcast::channel(256);
        (
            Self {
                components: HashMap::new(),
                leases: HashMap::new(),
                watch_tx: tx.clone(),
            },
            tx,
        )
    }
}

