syntax = "proto3";

package emqx.exhook.v1;

// EMQX ExHook gRPC API - HookProvider service
// EMQX acts as gRPC client, calling this service for MQTT events

service HookProvider {
  // Client lifecycle hooks
  rpc OnClientConnect(OnClientConnectRequest) returns (OnClientConnectResponse);
  rpc OnClientConnack(OnClientConnackRequest) returns (OnClientConnackResponse);
  rpc OnClientConnected(OnClientConnectedRequest) returns (OnClientConnectedResponse);
  rpc OnClientDisconnected(OnClientDisconnectedRequest) returns (OnClientDisconnectedResponse);
  rpc OnClientSubscribe(OnClientSubscribeRequest) returns (OnClientSubscribeResponse);
  rpc OnClientUnsubscribe(OnClientUnsubscribeRequest) returns (OnClientUnsubscribeResponse);

  // Message hooks
  rpc OnMessagePublish(OnMessagePublishRequest) returns (OnMessagePublishResponse);
  rpc OnMessageDelivered(OnMessageDeliveredRequest) returns (OnMessageDeliveredResponse);
  rpc OnMessageAcked(OnMessageAckedRequest) returns (OnMessageAckedResponse);

  // Session hooks
  rpc OnSessionCreated(OnSessionCreatedRequest) returns (OnSessionCreatedResponse);
  rpc OnSessionSubscribed(OnSessionSubscribedRequest) returns (OnSessionSubscribedResponse);
  rpc OnSessionUnsubscribed(OnSessionUnsubscribedRequest) returns (OnSessionUnsubscribedResponse);
  rpc OnSessionGotOfflineMsgs(OnSessionGotOfflineMsgsRequest) returns (OnSessionGotOfflineMsgsResponse);
  rpc OnSessionDiscardedMsgs(OnSessionDiscardedMsgsRequest) returns (OnSessionDiscardedMsgsResponse);

  // Telemetry hooks
  rpc OnThrottle(ThrottleRequest) returns (ThrottleResponse);
}

// Client info message
message ClientInfo {
  string clientid = 1;
  string username = 2;
  string peerhost = 3;
  string node = 4;
}

message OnClientConnectRequest {
