//! op-web: Main Entry Point
//!
//! Unified web server for op-dbus-v2.

use std::net::SocketAddr;
use std::sync::Arc;
use tracing::info;
use tracing_subscriber::{EnvFilter, FmtSubscriber};

use op_web::routes;
use op_web::AppState;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    // Initialize logging with environment filter (RUST_LOG)
    // Default to info if not set
    let filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));

    let _ = FmtSubscriber::builder()
        .with_env_filter(filter)
        .with_target(false)
        .with_thread_ids(false)
        .compact()
        .try_init();

    info!("Starting op-web server...");
    info!("Version: {}", env!("CARGO_PKG_VERSION"));

    // Absolute Base: without a sealed blob catalog in shared memory, the entity
    // does not exist. The sealed blob catalog (op-blob) is the single source of
    // truth for "which plugins exist"; the sled-tail and live-schema.json
    // monolith are deprecated and no longer written.
    match op_blob::catalog::read_manifest_plugin_ids_shm() {
        Some(ids) if !ids.is_empty() => {
            info!(
                plugins = ids.len(),
                "Sealed blob catalog present in shared memory"
            );
        }
        _ => {
            tracing::error!(
                dir = op_blob::catalog::DEFAULT_SHM_DIR,
                "FATAL: Sealed blob catalog missing from shared memory. Start the blob sealer / projection first."
            );
            std::process::exit(1);
        }
    }

    let state = Arc::new(AppState::new().await?);
    state.clone().start_event_bridge();

