}
message OnMessagePublishResponse {
  bool success = 1;
  string error = 2;
}

message OnMessageDeliveredRequest {
  ClientInfo client = 1;
  string topic = 2;
  bytes payload = 3;
  uint32 qos = 4;
}
message OnMessageDeliveredResponse {
  bool success = 1;
  string error = 2;
}

message OnMessageAckedRequest {
  ClientInfo client = 1;
  string topic = 2;
  uint32 qos = 3;
}
message OnMessageAckedResponse {
  bool success = 1;
  string error = 2;
}

message OnSessionCreatedRequest {
  ClientInfo client = 1;
}
message OnSessionCreatedResponse {
  bool success = 1;
  string error = 2;
}

message OnSessionSubscribedRequest {
  ClientInfo client = 1;
  string topic = 2;
  uint32 qos = 3;
}
message OnSessionSubscribedResponse {
  bool success = 1;
