pub struct HookProviderService {
    mutation_engine: std::sync::Arc<MutationEngine>,
}

impl HookProviderService {
    pub fn new(mutation_engine: std::sync::Arc<MutationEngine>) -> Self {
        Self { mutation_engine }
    }

    /// Record an EMQX event as a signal mutation.
    async fn record_event(
        &self,
        event_type: &str,
        client_id: &str,
        topic: Option<&str>,
        payload: Option<&str>,
    ) -> anyhow::Result<()> {
        let mut event_data = simd_json::json!({
            "event_type": event_type,
            "client_id": client_id,
        });

        if let Some(t) = topic {
            event_data["topic"] = simd_json::json!(t);
        }
        if let Some(p) = payload {
            event_data["payload"] = simd_json::json!(p);
